    class Program

    {
        static Random random = new Random();
        static void Main(string[] args)
        {

            Player player = LoadPlayer(); // Загружаем игрока из сохранения

            // Цикл игры
            while (true)
            {
                Console.WriteLine($"\nВаш уровень: {player.Level}, HP: {player.HP}, XP: {player.XP}, Gold: {player.Gold}");
                Console.WriteLine("Build version 1.0.1");

                // Выбор действия
                Console.WriteLine("\nЧто ты будешь делать?");
                Console.WriteLine("1. Двигаться вперед");
                Console.WriteLine("2. Изучить окрестности");
                Console.WriteLine("3. Проверить инвентарь");
                Console.WriteLine("4. Использовать предмет");
                Console.WriteLine("5. Сохранить игру");
                Console.WriteLine("6. Сбросить прогресс");
                Console.WriteLine("7. Магазин");
                Console.WriteLine("8. Примечания и благодарности");

                int choice = GetIntInput(1, 8);

                switch (choice)
                {
                    case 1:
                        // Двигаться вперед
                        MoveForward(player);
                        break;

                    case 2:
                        // Изучить окрестности
                        Explore(player);
                        break;

                    case 3:
                        // Проверить инвентарь
                        CheckInventory(player);
                        break;

                    case 4:
                        // Использовать предмет
                        UseItem(player);
                        break;

                    case 5:
                        // Сохранить игру
                        SavePlayer(player);
                        Console.WriteLine("Игра сохранена.");

                        break;

                    case 6:
                        // Сбросить прогресс
                        ResetProgress();
                        Console.WriteLine("Прогресс сброшен! Начинаем заново!");
                        Console.WriteLine("Создание нового персонанажа!");
                        Console.WriteLine("...");
                        Console.WriteLine("Персонаж создан!");
                        player = new Player("Герой", 100, 2, 0); // Создаем нового игрока
                        break;

                    case 7:
                        Shop(player);
                        break;

                    case 8:
                        Console.WriteLine("UndertaleConsole - Примечания и Благодарности\r\n\r\nАвтор: Dotick.M\r\n\r\nТехнологии:\r\n\r\n* C#\r\n\r\nБлагодарности:\r\n\r\n* C# - за мощные возможности для реализации игровых механик и интерфейсов.\r\n* Всем, кто вдохновил меня на создание этой игры, особенно создателям Undertale за их замечательный мир и персонажей.\r\n\r\nПримечания:\r\n* Игра находится в стадии разработки и может содержать ошибки.");
                        break;


                }

                
                // Проверка состояния игрока
                if (player.HP <= 0)
                {
                    Console.ForegroundColor = ConsoleColor.Red;
                    Console.WriteLine("\nТы проиграл... Тебя убил монстр.");
                    Console.WriteLine("Игра окончена.");
                    Console.ResetColor();

                    Console.WriteLine("\nНажми Enter, чтобы загрузить последнее сохранение...");
                    Console.ReadLine(); // Игра остановится и подождет, пока ты нажмешь Enter

                    player = LoadPlayer(); // Загружаем сохранение

                    // Защита от бесконечной смерти (если сохранился с 0 HP)
                    if (player.HP <= 0)
                    {
                        player.HP = 100;
                    }

                    continue; // ВАЖНО! Отправляет игру в начало цикла while (true), а не закрывает её
                }
                else if (player.Location == "Выход")
                {
                    // Окончание игры
                    if (player.XP >= 1000 && player.Gold >= 3000)
                    {
                        Console.WriteLine("\nТы победил! Тебе удалось выбраться из подземелья.");
                        Console.WriteLine("Поздравляем! Ты получил Золотую концовку!");

                        // Бой с Золотым Сансом
                        Console.WriteLine("\nНо перед тем, как ты сможешь уйти, появляется Золотой Санс...");
