        static void Shop(Player player)
        {
            while (true)
            {
                Console.WriteLine($"\n=== МАГАЗИН === (У тебя {player.Gold} золота)");
                Console.WriteLine("1. Купить предметы");
                Console.WriteLine("2. Продать предметы");
                Console.WriteLine("3. Выйти");

                int action = GetIntInput(1, 3);

                if (action == 3)
                {
                    Console.WriteLine("Ты вышел из магазина.");
                    break;
                }

                // ПОКУПКА
                if (action == 1)
                {
                    Console.WriteLine("\nЧто желаешь купить?");
                    Console.WriteLine("1. Монстрская конфета (+10 HP) - 15 золота");
                    Console.WriteLine("2. Паучий пончик (+12 HP) - 18 золота");
                    Console.WriteLine("3. Мороженое (+15 HP) - 25 золота");
                    Console.WriteLine("4. Морской чай (+15 HP) - 25 золота");
                    Console.WriteLine("5. Крабовое яблоко (+18 HP) - 30 золота");
                    Console.WriteLine("6. Гламбургер (+27 HP) - 45 золота");
                    Console.WriteLine("7. Овощная лапша (+40 HP) - 60 золота");
                    Console.WriteLine("8. Назад");

                    int buyChoice = GetIntInput(1, 8);

                    switch (buyChoice)
                    {
                        case 1:
                            if (player.Gold >= 15) { player.Gold -= 15; player.Items.Add("Монстрская конфета"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 2:
                            if (player.Gold >= 18) { player.Gold -= 18; player.Items.Add("Паучий пончик"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 3:
                            if (player.Gold >= 25) { player.Gold -= 25; player.Items.Add("Мороженое"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 4:
                            if (player.Gold >= 25) { player.Gold -= 25; player.Items.Add("Морской чай"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 5:
                            if (player.Gold >= 30) { player.Gold -= 30; player.Items.Add("Крабовое яблоко"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 6:
                            if (player.Gold >= 45) { player.Gold -= 45; player.Items.Add("Гламбургер"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 7:
                            if (player.Gold >= 60) { player.Gold -= 60; player.Items.Add("Овощная лапша"); Console.WriteLine("Куплено!"); }
                            else { Console.WriteLine("Недостаточно золота!"); }
                            break;
                        case 8:
                            break; // Выход в предыдущее меню
                    }
                }

                // ПРОДАЖА
                else if (action == 2)
                {
                    Console.WriteLine("\nЧто желаешь продать?");
                    CheckInventory(player);

                    if (player.Items.Count == 0)
                    {
                        continue; // Если пусто, возвращаемся в меню магазина
                    }

                    Console.WriteLine("Введи номер предмета (или 0, чтобы отменить):");
                    int itemChoice = GetIntInput(0, player.Items.Count);

                    if (itemChoice == 0) continue;

                    string itemToSell = player.Items[itemChoice - 1];
                    int sellPrice = 0;

                    // Определяем цену продажи (в 2-3 раза дешевле покупки)
                    switch (itemToSell)
                    {
                        case "Монстрская конфета": sellPrice = 5; break;
                        case "Паучий пончик": sellPrice = 7; break;
                        case "Мороженое": sellPrice = 10; break;
                        case "Морской чай": sellPrice = 10; break;
                        case "Крабовое яблоко": sellPrice = 12; break;
                        case "Гламбургер": sellPrice = 20; break;
                        case "Овощная лапша": sellPrice = 25; break;
                        case "Легендарный герой": sellPrice = 0; break; // Его нельзя продать
                    }

                    if (sellPrice > 0)
                    {
                        player.Gold += sellPrice;
                        player.Items.RemoveAt(itemChoice - 1);
                        Console.WriteLine($"Ты продал {itemToSell} и получил {sellPrice} золота.");
                    }
                    else
                    {
                        Console.WriteLine("Этот предмет нельзя продать (слишком ценен!).");
                    }
                }
            }
        }
        // Изучение окрестностей
        // Изучение окрестностей
        static void Explore(Player player)
        {
            Console.WriteLine("\nТы изучаешь окрестности...");

            // Выбор случайного события от 1 до 7
            int eventChoice = random.Next(1, 8);

            switch (eventChoice)
            {
                case 1:
                    // Шанс 30% найти записку (рандом от 1 до 10, выпадает 1, 2 или 3)
                    if (random.Next(1, 11) <= 3)
                    {
                        Console.WriteLine("Ты нашел старую записку с подсказкой.");
                        player.XP += 5;
                        Console.WriteLine("Ты получил 5 XP!");
                    }
                    else
                    {
                        Console.WriteLine("Ты внимательно осмотрелся, но не нашел ничего полезного.");
                    }
                    break;

                case 2:
                    // Поговори с NPC
                    Console.WriteLine("Ты встретил странного персонажа.");
                    Console.WriteLine("1. Поговорить с ним");
                    Console.WriteLine("2. Пройти мимо");

                    int npcChoice = GetIntInput(1, 2);
                    if (npcChoice == 1)
                    {
                        Console.WriteLine("Персонаж рассказал тебе о секретном проходе.");
                        player.Location = "Секретный проход";
                        player.XP += 10;
                    }
                    else
                    {
                        Console.WriteLine("Ты проигнорировал персонажа.");
                    }
                    break;

                case 3:
                    // Дупло в дереве
                    Console.WriteLine("Ты увидел дерево");
                    Console.WriteLine("В нем дупло");
                    Console.WriteLine("Вы вполне можете в него пролезть");
                    Console.WriteLine("1. Пролезть в дупло");
                    Console.WriteLine("2. Пройти мимо");

                    int puzzle = GetIntInput(1, 2);
                    if (puzzle == 1)
                    {
                        Console.WriteLine("Вы попались в ловушку!");
                        Console.WriteLine("Ну как сказать...");
                        Console.WriteLine("Вы попадаете в конец!");
                        Console.WriteLine("Вас уже заждалась Андайн!");
                        player.Location = "Местоположение босса Андайн";
                    }
                    else
                    {
                        Console.WriteLine("Ты проигнорировал дупло");
                    }
                    break;

                case 4:
                    // Внезапная встреча с врагом (Баланс)
                    Console.WriteLine("Ты забрел в темные заросли...");

                    int ambushChoice = random.Next(1, 5);
                    Enemy ambushEnemy;

                    switch (ambushChoice)
                    {
                        case 1:
                            ambushEnemy = new Froggit(10);
                            player.Items.Add("Монстрская конфета");
                            Console.WriteLine("Фроггит уронил Монстрскую конфету!");
                            Console.ForegroundColor = ConsoleColor.Red;
                            Console.WriteLine("Внезапно из кустов выпрыгнул Фроггит!");
                            Console.ResetColor();
                            break;
                        case 2:
                            ambushEnemy = new Temmie(15);
                            player.Items.Add("Мороженое");
                            Console.WriteLine("Темми уронила Мороженое!");
                            Console.ForegroundColor = ConsoleColor.Red;
                            Console.WriteLine("Из-за угла выбежала Темми и требует еды!");
                            Console.ResetColor();
                            break;
                        case 3:
                            ambushEnemy = new Moldsmall(15);
                            player.Items.Add("Паучий пончик");
                            Console.WriteLine("Молдсмол уронил Паучий пончик!");
                            Console.ForegroundColor = ConsoleColor.Red;
                            Console.WriteLine("На тебя неожиданно накатился Молдсмол!");
                            Console.ResetColor();
                            break;
                        default: // Это case 4
                            ambushEnemy = new Tsunderplane(15);
                            player.Items.Add("Морской чай");
                            Console.WriteLine("Цундереплан уронила Морской чай!");
                            Console.ForegroundColor = ConsoleColor.Red;
                            Console.WriteLine("Цундереплан спикировала на тебя! (Не то чтобы она этого хотела...)");
                            Console.ResetColor();
                            break;
                    }

                    Fight(player, ambushEnemy);
                    break;

                case 5:
                    // Пещера
                    Console.WriteLine("Ты увидел пещеру");
                    Console.WriteLine("Ты можешь пройти");
                    Console.WriteLine("1. Пройти в пещеру");
                    Console.WriteLine("2. Пройти мимо");

                    int puzzle1 = GetIntInput(1, 2);
                    if (puzzle1 == 1)
                    {
                        Console.WriteLine("Вас привело...");
                        player.Location = "Секретный проход";
                    }
                    else
                    {
                        Console.WriteLine("Ты проигнорировал пещеру");
                    }
                    break;

                case 6:
                    // Телестудия MTT
                    Console.WriteLine("Ты увидел телестудию ");
                    Console.WriteLine("Дверь в неё открыта");
                    Console.WriteLine("Пройдёте ли вы в телестудию?");
                    Console.WriteLine("1. Пройти в зал ");
                    Console.WriteLine("2. Пройти мимо");

                    int puzzleMTT = GetIntInput(1, 2);
                    if (puzzleMTT == 1)
                    {
                        Console.WriteLine("Вас встретил MTT");
                        Console.WriteLine("Это наилучший телеведущий");
                        Console.WriteLine("Он ведёт программу");
                        Console.WriteLine("Торт из человека...");
                        player.Location = "MTT";
                    }
                    else
                    {
                        Console.WriteLine("Ты проигнорировал телестудию");
                    }
                    break;

                case 7:
                    // Просто пустое событие для баланса
                    Console.WriteLine("Ты долго бродил, но так ничего и не нашел. Зато ноги размял.");
                    break;
            }
        }


        // Проверка инвентаря
        static void CheckInventory(Player player)
        {
            Console.WriteLine("\nВ вашем инвентаре:");
            if (player.Items.Count == 0)
            {
                Console.WriteLine("Ничего нет.");
            }
            else
            {
                foreach (string item in player.Items)
                {
                    Console.WriteLine(item);
                }
            }
        }

        // Использовать предмет
        static void UseItem(Player player)
        {
            Console.WriteLine("\nКакой предмет ты хочешь использовать?");
            CheckInventory(player);

            if (player.Items.Count == 0)
            {
                Console.WriteLine("У тебя нет предметов.");
                return;
            }

            Console.WriteLine("Введите номер предмета (или 0, чтобы отменить):");
            int itemChoice = GetIntInput(0, player.Items.Count);

            if (itemChoice == 0)
            {
                return;
            }

            string item = player.Items[itemChoice - 1];

            if (item == "Монстрская конфета")
            {
                player.HP += 10;
                Console.WriteLine("Ты съел Монстрскую конфету. Она странно хрустит... Надеюсь, это просто сахар. Восстановлено 10 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Паучий пончик")
            {
                player.HP += 12;
                Console.WriteLine("Ты съел Паучий пончик. Внутри было что-то липкое и хрустящее. Пальчики оближешь! Восстановлено 12 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Мороженое")
            {
                player.HP += 15;
                Console.WriteLine("Ты съел Мороженое. На обертке написано: \"Ты классный!\". Стало немного холодно, но приятно. Восстановлено 15 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Морской чай")
            {
                player.HP += 15;
                Console.WriteLine("Ты выпил Морской чай. На вкус как соленая вода с травами, но ты чувствуешь прилив сил. Восстановлено 15 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Крабовое яблоко")
            {
                player.HP += 18;
                Console.WriteLine("Ты съел Крабовое яблоко. Оно хрустит и слегка щиплет язык. Восстановлено 18 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Овощная лапша")
            {
                player.HP += 40;
                Console.WriteLine("Ты съел Овощную лапшу. Она была сухой, но ты справился! Пальчики оближешь. Восстановлено 40 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Гламбургер")
            {
                player.HP += 27;
                Console.WriteLine("Ты съел Гламбургер. Внутри 100% гламура и 0% мяса. Вкус победы! Восстановлено 27 HP.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else if (item == "Легендарный герой")
            {
                player.HP += 40;
                player.Attack += 4;
                Console.WriteLine("Ты съел Легендарного героя. Ты чувствуешь себя непобедимым! Восстановлено 40 HP и +4 к атаке.");
                player.Items.RemoveAt(itemChoice - 1);
            }
            else

            {
                Console.WriteLine("Неизвестный предмет.");
            }
        }

        // Система боя
        static void Fight(Player player, Enemy enemy)
        {
            Console.WriteLine($"\nHP врага: {enemy.HP}");

            while (player.HP > 0 && enemy.HP > 0)
            {
                Console.WriteLine($"Ваш HP: {player.HP}");
                Console.WriteLine("\nЧто ты будешь делать?");
                Console.WriteLine("1. Атака");
                Console.WriteLine("2. Защита");
                Console.WriteLine("3. Использовать предмет");

                int choice = GetIntInput(1, 3);

                bool isDefending = false;

                switch (choice)
                {
                    case 1:
                        Console.WriteLine("Ты атакуешь врага!");
                        enemy.HP -= player.Attack;
                        Console.WriteLine($"Врагу нанесено {player.Attack} урона. Осталось {enemy.HP} HP.");
                        break;

                    case 2:
                        Console.WriteLine("Ты защищаешься!");
                        isDefending = true;
                        break;

                    case 3:
                        UseItem(player);
                        break;
                }

                // Ход врага — ровно один раз
                if (enemy.HP > 0)
                {
                    if (isDefending)
                    {
                        // Шанс 35%, что враг промахнётся и ударит сам себя
                        if (random.Next(1, 101) <= 35)
                        {
                            int selfDamage = Math.Max(1, enemy.Attack / 2);
                            enemy.HP -= selfDamage;

                            Console.ForegroundColor = ConsoleColor.Green;
                            Console.WriteLine("\nВраг замахивается... но промахивается и бьёт сам себя!");
                            Console.WriteLine($"Враг получил {selfDamage} урона. Осталось {enemy.HP} HP.");
                            Console.ResetColor();
                        }
                        else
                        {
                            int damage = Math.Max(1, enemy.Attack / 2);
                            player.HP -= damage;

                            Console.WriteLine("\nВраг атакует! Ты блокируешь часть удара.");
                            Console.WriteLine($"Ты получил {damage} урона.");
                        }
                    }
                    else
                    {
                        Console.WriteLine("\nВраг атакует!");
                        player.HP -= enemy.Attack;
                        Console.WriteLine($"Ты получил {enemy.Attack} урона.");
                    }
                }
            } // ← while закрывается здесь

            // Итог боя — один раз, после цикла
            if (player.HP <= 0)
            {
                Console.WriteLine("\nТы проиграл битву...");
                Console.ResetColor();
            }
            else
            {
                Console.WriteLine("\nТы победил!");
                player.Gold += enemy.GoldReward;
                player.XP += enemy.XPReward;
                Console.WriteLine($"Ты получил {enemy.GoldReward} золота и {enemy.XPReward} XP.");
                Console.ResetColor();

                // Проверка уровня — while, чтобы поднять сразу несколько, если XP хватает
                while (player.XP >= player.Level * 10)
                {
                    player.Level++;
                    player.HP += 10;
                    player.Attack += 1;
                    Console.WriteLine("Поздравляем! Вы повысили уровень!");
                }
            }
        }

        // Сохранение игры
        // Сохранение игры
        static void SavePlayer(Player player)
        {
            try
            {
                // Склеиваем все предметы из инвентаря в одну строку через вертикальную черту "|"
                string itemsString = string.Join("|", player.Items);

                // Добавляем эту строку в конец наших данных
                string saveData = $"{player.Name},{player.HP},{player.Attack},{player.Gold},{player.XP},{player.Level},{player.Location},{itemsString}";

                File.WriteAllText("save.txt", saveData);
            }
            catch (Exception ex)
            {
                Console.WriteLine("Ошибка при сохранении: " + ex.Message);
            }
        }

        // Загрузка игры
        // Загрузка игры
        static Player LoadPlayer()
        {
            Player player = new Player("Герой", 100, 2, 0); // Начальный урон 2

            if (File.Exists("save.txt"))
            {
                try
                {
                    string[] data = File.ReadAllText("save.txt").Split(',');

                    if (data.Length < 7)
                        throw new FormatException("В сохранении недостаточно данных.");

                    player.Name = data[0];
                    player.HP = int.Parse(data[1]);
                    player.Attack = int.Parse(data[2]);
                    player.Gold = int.Parse(data[3]);
                    player.XP = int.Parse(data[4]);
                    player.Level = int.Parse(data[5]);
                    player.Location = data[6];

                    // ЗАГРУЗКА ИНВЕНТАРЯ (если он есть в файле)
                    if (data.Length > 7 && !string.IsNullOrEmpty(data[7]))
                    {
                        string[] loadedItems = data[7].Split('|'); // Разбиваем строку обратно на предметы
                        foreach (string item in loadedItems)
                        {
                            player.Items.Add(item);
                        }
                    }

                    Console.WriteLine("Игра загружена.");
                }
                catch (IndexOutOfRangeException)
                {
                    Console.WriteLine("Сохранение повреждено (мало данных). Начинаем новую игру.");
                }
                catch (FormatException)
                {
                    Console.WriteLine("В сохранении записано не число. Начинаем новую игру.");
                }
                catch (Exception ex)
                {
                    Console.WriteLine("Не удалось загрузить сохранение: " + ex.Message);
                    Console.WriteLine("Начинаем новую игру.");
                }
            }
            else
            {
                Console.WriteLine("Сохранения не найдено. Новая игра.");
            }

            return player;
        }

        // Сброс прогресса
        static void ResetProgress()
        {
            try
            {
                if (File.Exists("save.txt"))
                {
                    File.Delete("save.txt");
                    Console.WriteLine("Прогресс сброшен.");
                }
                else
                {
                    Console.WriteLine("Сбрасывать нечего — сохранения нет.");
                }
            }
            catch (IOException ex)
            {
                Console.WriteLine("Не удалось удалить файл: " + ex.Message);
            }
        }


        // Класс игрока
        class Player
        {
            public string Name { get; set; }
            public int HP { get; set; }
            public int Attack { get; set; }
            public int Gold { get; set; }
            public int XP { get; set; }
            public int Level { get; set; }
            public List<string> Items { get; set; }
            public string Location { get; set; }

            public Player(string name, int hp, int attack, int xp)
            {
                Name = name;
                HP = hp;
                Attack = attack;
                Gold = 0;
                XP = xp;
                Level = 1;
                Items = new List<string>();
                Location = "Старт";
            }
        }

